def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        # Read the strings
        graph = {}
        for _ in range(n):
            a, b = map(int, input().split())
            if a not in graph:
                graph[a] = []
            if b not in graph:
                graph[b] = []
            graph[a].append(b)
            graph[b].append(a)

        # Find all nodes
        nodes = list(graph.keys())
        num_nodes = len(nodes)

        # Map node numbers to indices
        node_to_idx = {node: i for i, node in enumerate(nodes)}
        idx_to_node = {i: node for i, node in enumerate(nodes)}

        # Memoization table: dp[mask][current_idx] = max_length
        # mask is a bitmask representing visited nodes
        max_mask = 1 << num_nodes
        dp = [[-1] * num_nodes for _ in range(max_mask)]

        def dfs(mask, current_idx):
            # If we've already computed this state
            if dp[mask][current_idx] != -1:
                return dp[mask][current_idx]

            # Try all neighbors
            max_len = 1  # At least the current node itself
            current_node = idx_to_node[current_idx]
            for neighbor in graph[current_node]:
                neighbor_idx = node_to_idx[neighbor]
                if not (mask & (1 << neighbor_idx)):
                    # Neighbor not visited
                    new_mask = mask | (1 << neighbor_idx)
                    length = 1 + dfs(new_mask, neighbor_idx)
                    max_len = max(max_len, length)

            dp[mask][current_idx] = max_len
            return max_len

        # Try all starting nodes
        max_chain_length = 0
        for start_idx in range(num_nodes):
            max_chain_length = max(max_chain_length, dfs(1 << start_idx, start_idx))

        print(max_chain_length)

solve()
