import sys

def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        # Place queen at (1, 1)
        print("1 1")
        sys.stdout.flush()

        # Sweep pattern: right, down, left, up
        queen_pos = (1, 1)

        for move in range(130):
            # Calculate next position
            if queen_pos[0] == 1 and queen_pos[1] < 8:
                new_pos = (1, queen_pos[1] + 1)
            elif queen_pos[0] < 8 and queen_pos[1] == 8:
                new_pos = (queen_pos[0] + 1, 8)
            elif queen_pos[0] == 8 and queen_pos[1] > 1:
                new_pos = (8, queen_pos[1] - 1)
            elif queen_pos[0] > 1 and queen_pos[1] == 1:
                new_pos = (queen_pos[0] - 1, 1)
            else:
                # If we're in the middle, we need a different strategy
                # Let's just move right for simplicity
                new_pos = (queen_pos[0], queen_pos[1] + 1)

            # Print and flush
            print(f"{new_pos[0]} {new_pos[1]}")
            sys.stdout.flush()

            # Read king's move
            response = sys.stdin.readline().strip()
            if response == "Done":
                break

            # Update queen position
            queen_pos = new_pos

if __name__ == "__main__":
    solve()
"}

