def get_third_smallest_largest(digits):
    """Return the 3rd smallest and 3rd largest numbers that can be formed."""

    # Count frequency of each digit
    freq = [0] * 10
    for d in digits:
        freq[int(d)] += 1

    # Get sorted digits
    sorted_asc = sorted(digits)
    sorted_desc = sorted(digits, reverse=True)

    # Function to generate all permutations
    def generate_permutations(start_digit, remaining_digits):
        """Generate all permutations starting with start_digit."""
        if not remaining_digits:
            return [start_digit]

        perms = []
        for i, d in enumerate(remaining_digits):
            if d == start_digit:
                continue  # Skip duplicates

            new_remaining = remaining_digits[:i] + remaining_digits[i+1:]
            for perm in generate_permutations(d, new_remaining):
                perms.append(start_digit + perm)

        return perms

    # Generate all permutations
    all_perms = generate_permutations('', sorted_asc)

    # Sort and find 3rd smallest and 3rd largest
    all_perms.sort()

    if len(all_perms) < 3:
        return "Not possible!"

    third_smallest = all_perms[2]
    third_largest = all_perms[-3]

    return f"{third_smallest} {third_largest}"

def solve():
    T = int(input())
    for _ in range(T):
        N = input().strip()

        if len(N) < 3:
            print("Not possible!")
        else:
            result = get_third_smallest_largest(N)
            print(result)

solve()
"}

