def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    Q = int(next(it))

    words = []
    for _ in range(N):
        words.append(next(it))

    # Build prefix to words map
    prefix_to_words = {}
    for word in words:
        prefix_to_words[word] = word

    # Process queries
    out = []
    for _ in range(Q):
        p = next(it)
        s = next(it)

        count = 0
        for word in words:
            if word.startswith(p) and word.endswith(s):
                count += 1
        out.append(str(count))

    sys.stdout.write("\n".join(out))

