def can_reach(target, remaining_chars, protein_values):
    """Check if we can reach the target sum with remaining characters."""
    # Count how many of each character we have
    char_count = {}
    for c in remaining_chars:
        char_count[c] = char_count.get(c, 0) + 1

    # Try all combinations of characters
    # This is a simple backtracking approach
    def backtrack(pos, current_sum, path):
        if pos == len(remaining_chars):
            return current_sum == target

        c = remaining_chars[pos]
        # Try not taking this character
        if backtrack(pos + 1, current_sum, path):
            return True

        # Try taking this character
        if char_count[c] > 0:
            char_count[c] -= 1
            if backtrack(pos + 1, current_sum + protein_values[ord(c) - ord('a')], path + [c]):
                return True
            char_count[c] += 1

    return backtrack(0, 0, [])

