import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n

        # Check if it's already valid
        valid = True
        for i in range(n-1):
            if (a[i] % 2) == (a[i+1] % 2):
                valid = False
                break

        if valid:
            results.append(0)
            continue

        # Try to fix by swapping
        swaps = 0
        i = 0
        while i < n - 1:
            # Check if current and next have same parity
            if (a[i] % 2) == (a[i+1] % 2):
                # Need to fix
                # Try to swap with next element
                if i + 2 < n and (a[i+2] % 2) != (a[i] % 2):
                    # Swap i+1 and i+2
                    a[i+1], a[i+2] = a[i+2], a[i+1]
                    swaps += 1
                    i += 1  # Move past the fixed position
                else:
                    # Can't fix, return -1
                    results.append(-1)
                    break
            else:
                i += 1

        else:
            # If we exited the loop normally, check if valid
            valid = True
            for i in range(n-1):
                if (a[i] % 2) == (a[i+1] % 2):
                    valid = False
                    break

            if valid:
                results.append(swaps)
            else:
                results.append(-1)

    sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()
