import math

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Find all primes up to max a_i
    max_val = max(a)
    is_prime = [True] * (max_val + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(max_val)) + 1):
        if is_prime[i]:
            for j in range(i * i, max_val + 1, i):
                is_prime[j] = False

    # Count prime exponents for each number
    prime_counts = {}
    for num in a:
        if num == 1:
            continue
        temp = num
        for p in range(2, max_val + 1):
            if is_prime[p] and temp % p == 0:
                cnt = 0
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                if p not in prime_counts:
                    prime_counts[p] = []
                prime_counts[p].append(cnt)

    # Compute answer
    result = 1
    for p in prime_counts:
        exponents = prime_counts[p]
        if len(exponents) < 2:
            continue
        exponents.sort()
        # min max(e_i, e_j) = max of two smallest
        min_max = max(exponents[0], exponents[1])
        result *= p ** min_max

    print(result)

