def count_lucky_numbers(n):
    """Count how many lucky numbers are lexicographically smaller than n"""
    count = 0
    digit_count = len(n)

    # Count numbers with fewer digits
    for k in range(1, digit_count):
        count += 2 ** k

    # Count numbers with the same number of digits that are lexicographically smaller
    for i in range(digit_count):
        # For each position, count how many numbers start with a smaller digit
        # at this position and have the same number of digits
        for digit in [4, 7]:
            if digit < int(n[i]):
                # Count how many numbers have this digit at this position
                # and the rest can be anything
                count += 2 ** (digit_count - i - 1)
            elif digit == int(n[i]):
                # Move to the next position
                break
            else:
                # digit > int(n[i]), no need to count
                pass

    return count + 1  # Add 1 for the number itself

def solve():
    n = input().strip()
    print(count_lucky_numbers(n))

