    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Read n binary strings
        rows = []
        for _ in range(n):
            row = next(it)
            rows.append(row)

        # Check each column
        found = False
        for col in range(m):
            # Create list of rows without the current column
            new_rows = [row[:col] + row[col+1:] for row in rows]

            # Check if all new rows are unique
            if are_all_unique(new_rows):
                found = True
                break

        print("Yes" if found else "No")

