{"code": "
import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])

    # Track participants and their point history
    participants = {}

    for i in range(1, n + 1):
        line = data[i].strip()
        name, points = line.split('\t')
        points = int(points)

        if name not in participants:
            participants[name] = []

        # Update points
        if points >= 0:
            participants[name].append((i, participants[name][-1][1] + points))
        else:
            # If points are negative, we need to track the actual points
            # But the problem says we just add the points
            participants[name].append((i, participants[name][-1][1] + points))

    # Find the maximum points
    max_points = max([points for points in [participant[-1][1] for participant in participants.values()]])

    # Find who reached max_points first
    first_to_max = None
    for name, history in participants.items():
        for round_num, points in history:
            if points >= max_points:
                if first_to_max is None or round_num < first_to_max[0]:
                    first_to_max = (round_num, name)
                break  # We only care about the first time they reach max_points

    print(first_to_max[1])

if __name__ == "__main__":
    solve()
