import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    # Union-Find data structure
    parent = list(range(N + 1))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu != pv:
            parent[pu] = pv

    # Read friendships
    friends = {}
    for _ in range(M):
        a = int(next(it))
        b = int(next(it))

        # Union for friends
        union(a, b)

        # Track friends
        friends[a] = friends.get(a, set()) | {b}
        friends[b] = friends.get(b, set()) | {a}

    # Read blockships
    blockships = {}
    for _ in range(K):
        c = int(next(it))
        d = int(next(it))

        # Track blockships
        blockships[c] = d
        blockships[d] = c

    # Calculate results
    result = []
    for i in range(1, N + 1):
        component = find(i)

        # Count users in the same component
        total_in_component = 0
        for j in range(1, N + 1):
            if find(j) == component:
                total_in_component += 1

        # Subtract direct friends
        total = total_in_component - 1  # exclude self
        total -= len(friends.get(i, set()))

        # Subtract direct blockships
        if i in blockships:
            total -= 1

        result.append(str(total))

    print(' '.join(result))

if __name__ == '__main__':
    solve()
