def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)  # For transposed graph

    # Dijkstra's algorithm
    INF = 10**18
    dist = [[INF] * (n + 1) for _ in range(n + 1)]  # dist[vertex][transposition_count]
    dist[1][0] = 0

    # Priority queue: (cost, vertex, transposition_count)
    heap = [(0, 1, 0)]

    while heap:
        cost, u, k = heapq.heappop(heap)

        if u == n:
            print(cost % 998244353)
            return

        if cost > dist[u][k]:
            continue

        # Move along an edge
        for v in adj[u]:
            if k % 2 == 0:
                # Original graph: u -> v
                if v in adj[u]:
                    if dist[v][k] > cost + 1:
                        dist[v][k] = cost + 1
                        heapq.heappush(heap, (dist[v][k], v, k))
            else:
                # Transposed graph: v -> u
                if u in adj[v]:
                    if dist[u][k] > cost + 1:
                        dist[u][k] = cost + 1
                        heapq.heappush(heap, (dist[u][k], u, k))

        # Transpose the graph
        if k + 1 <= n:
            trans_cost = 1 << k  # 2^k
            if dist[u][k + 1] > cost + trans_cost:
                dist[u][k + 1] = cost + trans_cost
                heapq.heappush(heap, (dist[u][k + 1], u, k + 1))

    print(-1)

if __name__ == "__main__":
