def comb(n, k, mod):
    """Compute combination C(n, k) modulo mod"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    # Iterative approach to compute C(n, k)
    # C(n, k) = n * (n-1) * ... * (n-k+1) / (k * (k-1) * ... * 1)
    # We'll compute numerator and denominator separately
    numerator = 1
    for i in range(k):
        numerator = (numerator * (n - i)) % mod
    denominator = 1
    for i in range(1, k+1):
        denominator = (denominator * i) % mod
    # Compute modular inverse of denominator
    # Since mod is prime (777777777 is prime?), we can use Fermat's little theorem
    # Check if mod is prime
    # 777777777 = 7 * 111111111 = 7 * 3 * 37037037 = 7 * 3 * 3 * 12345679
    # Actually, 777777777 = 7 * 111111111 = 7 * 3 * 37037037 = 7 * 3 * 3 * 12345679
    # So it's not prime
    # We need to compute modular inverse using extended Euclidean algorithm
    def modinv(a, m):
        """Compute modular inverse of a modulo m using extended Euclidean algorithm"""
        g, x, y = extended_gcd(a, m)
        if g != 1:
            return None  # No inverse exists
        return x % m

    def extended_gcd(a, b):
        """Extended Euclidean algorithm"""
        if a == 0:
            return (b, 0, 1)
        else:
            g, y, x = extended_gcd(b % a, a)
            return (g, x - (b // a) * y, y)

    inv_denominator = modinv(denominator, mod)
    if inv_denominator is None:
        return 0  # No inverse exists
    return (numerator * inv_denominator) % mod

def pow_mod(base, exp, mod):
    """Compute base^exp mod mod"""
    result = 1
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

n, k = map(int, input().split())
mod = 777777777

