import sys

def is_beneficial(i):
    """Determine if operation i is beneficial."""
    if i == 1:
        return True

    # Find p_max: prime with greatest exponent in prime factorization of i
    # If multiple primes have the same greatest exponent, choose the smallest

    # Prime factorization of i
    factors = {}
    temp = i

    # Check for 2
    count = 0
    while temp % 2 == 0:
        count += 1
        temp //= 2
    if count > 0:
        factors[2] = count

    # Check for odd primes
    p = 3
    while p * p <= temp:
        count = 0
        while temp % p == 0:
            count += 1
            temp //= p
        if count > 0:
            factors[p] = count
        p += 2

    if temp > 1:
        factors[temp] = 1

    # Find p_max
    max_exponent = max(factors.values())
    candidates = [p for p, exp in factors.items() if exp == max_exponent]
    p_max = min(candidates)

    # Check if p_max % i is odd
    return (p_max % i) % 2 == 1

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    L = int(data[1])
    A = list(map(int, data[2:2+N]))

    # Sort initially
    A.sort()

    for i in range(1, L + 1):
        if is_beneficial(i):
            # Beneficial: double the largest element
            if A:
                A[-1] *= 2
                A.sort()
        else:
            # Harmful: divide the smallest element by 2
            if A:
                A[0] //= 2
                if A[0] == 0:
                    A.pop(0)
                else:
                    A.sort()

    # Output
    print(len(A))
    if A:
        print(' '.join(map(str, A)))
    else:
        print()

if __name__ == "__main__":
    solve()
