def all_digits_identical(hour, minute):
    """Check if all digits in hour and minute are identical."""
    # Convert to strings
    hour_str = str(hour)
    minute_str = str(minute)

    # Check if all characters are the same
    first_char = hour_str[0]
    for ch in hour_str + minute_str:
        if ch != first_char:
            return False
    return True

def count_valid_times(H, M):
    """Count how many valid times have all identical digits."""
    count = 0

    for hour in range(H):
        for minute in range(M):
            if all_digits_identical(hour, minute):
                count += 1

    return count

def main():
    T = int(input())

    for _ in range(T):
        H, M = map(int, input().split())
        result = count_valid_times(H, M)
        print(result)

if __name__ == "__main__":
    main()
