def max_overlap(s, t):
    """Return the maximum overlap between string s and string t."""
    min_len = min(len(s), len(t))
    for k in range(min_len, -1, -1):
        if s.endswith(t[:k]):
            return k
    return 0

def solve():
    while True:
        line = input().strip()
        if not line:
            continue
        n = int(line)
        if n == 0:
            break

        cities = []
        for _ in range(n):
            cities.append(input().strip())

        # Precompute overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlap[i][j] = max_overlap(cities[i], cities[j])

        # DP: dp[mask][i] = minimum length of superstring covering cities in mask, ending with city i
        dp = [[float('inf')] * n for _ in range(1 << n)]

        # Initialize: single city
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # DP transition
        for mask in range(1, 1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue

                # Current length
                current_len = dp[mask][i]

                # Try to add each other city
                for j in range(n):
                    if mask & (1 << j):
                        continue

                    # New mask
                    new_mask = mask | (1 << j)

                    # Overlap between city i and city j
                    o = overlap[i][j]

                    # New length
                    new_len = current_len + len(cities[j]) - o

                    # Update DP
                    if new_len < dp[new_mask][j]:
                        dp[new_mask][j] = new_len

        # Find the minimum length covering all cities
        result = min(dp[(1 << n) - 1][i] for i in range(n))
        print(result)

