import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Use sliding window to find segments with exactly k distinct numbers
    distinct = {}
    left = 0
    result = -1, -1

    for right in range(n):
        distinct[a[right]] = distinct.get(a[right], 0) + 1

        # If we have more than k distinct, move left
        while len(distinct) > k:
            distinct[a[left]] -= 1
            if distinct[a[left]] == 0:
                del distinct[a[left]]
            left += 1

        # If we have exactly k distinct, check if this segment is minimal by inclusion
        if len(distinct) == k:
            # Check if we can remove elements from the start or end
            # and still have exactly k distinct
            can_remove_start = False
            can_remove_end = False

            # Check if we can remove from start
            if left + 1 <= right and len(distinct) == k:
                # Remove a[left]
                temp = distinct.copy()
                temp[a[left]] -= 1
                if temp[a[left]] == 0:
                    del temp[a[left]]
                if len(temp) == k:
                    can_remove_start = True

            # Check if we can remove from end
            if right - 1 >= left and len(distinct) == k:
                # Remove a[right]
                temp = distinct.copy()
                temp[a[right]] -= 1
                if temp[a[right]] == 0:
                    del temp[a[right]]
                if len(temp) == k:
                    can_remove_end = True

            # If we can't remove from start or end, this is minimal by inclusion
            if not can_remove_start and not can_remove_end:
                result = left + 1, right + 1  # Convert to 1-indexed
                break

    print(result[0], result[1])

if __name__ == "__main__":
    solve()
