    distinct = {}
    left = 0

    for right in range(n):
        # Add current element to the window
        if a[right] in distinct:
            distinct[a[right]] += 1
        else:
            distinct[a[right]] = 1
        \
        # If we have more than k distinct, move left pointer
        while len(distinct) > k:
            if distinct[a[left]] == 1:
                del distinct[a[left]]
            else:
